function Methods() {
  const modalRef = useRef(null);

  return (
    &lt;&gt;
      &lt;s-button
        command="--show"
        commandFor="modal-1"
      &gt;
        Open modal
      &lt;/s-button&gt;
      &lt;s-modal
        id="modal-1"
        ref={modalRef}
        heading="Test Modal"
      &gt;
        &lt;s-text&gt;Modal content&lt;/s-text&gt;
        &lt;s-button
          onClick={() =&gt; {
            modalRef.current.hideOverlay();
          }}
        &gt;
          Close modal
        &lt;/s-button&gt;
      &lt;/s-modal&gt;
    &lt;/&gt;
  );
}

function Methods() {
  const button =
    document.createElement('s-button');
  const modal = document.createElement('s-modal');

  button.textContent = 'Open Modal';
  button.commandFor = 'modal-1';

  modal.id = 'modal-1';
  modal.heading = 'Test Modal';

  const closeButton =
    document.createElement('s-button');

  closeButton.textContent = 'Close modal';
  closeButton.onclick = () =&gt; modal.hideOverlay();

  modal.appendChild(closeButton);

  document.body.appendChild(button);
  document.body.appendChild(modal);
}

